def cc(n):
    s = ''
    while n != 0:
        s = str(n % 8) +  s
        n //= 8
    return s

def f(n):
    s = cc(n)
    if s[0] == '5':
        s = s.replace('2','*').replace('1','2').replace('*','1')
        s = '11' + s
    else:
        s += '10'
        s = '2' + s[1:]
    return int(s,8)

